create table if not exists public.commercial_franchise_benchmarks (id uuid primary key default gen_random_uuid(),brand_name text not null unique,segment text,ranking_position integer,initial_investment_min numeric,initial_investment_max numeric,implementation_months_min numeric,implementation_months_max numeric,payback_months_min numeric,payback_months_max numeric,average_monthly_revenue numeric,break_even_monthly numeric,average_profit_margin_pct numeric,initial_team_size integer,source_name text,source_url text,source_reference_date date,selected_for_comparison boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.commercial_franchise_benchmarks enable row level security;
create policy commercial_franchise_benchmarks_read on public.commercial_franchise_benchmarks for select to authenticated using (active or public.current_app_role() in ('ADMIN','GESTOR'));
create policy commercial_franchise_benchmarks_manage on public.commercial_franchise_benchmarks for all to authenticated using (public.current_app_role() in ('ADMIN','GESTOR')) with check (public.current_app_role() in ('ADMIN','GESTOR'));
